import itertools

# Define the graph: C3 □ C3 (Cartesian product of two 3-cycles)
# Vertex labeling: v = 3*i + j, where i,j in {0,1,2}
edges = set()
for i in range(3):
    for j in range(3):
        v = 3*i + j
        # neighbor up: (i+1 mod 3, j)
        u = 3*((i+1)%3) + j
        if v < u:
            edges.add((v,u))
        else:
            edges.add((u,v))
        # neighbor right: (i, j+1 mod 3)
        u = 3*i + ((j+1)%3)
        if v < u:
            edges.add((v,u))
        else:
            edges.add((u,v))

edge_list = sorted(edges)
print("Number of edges:", len(edge_list))
print("Edges:", edge_list)

# Build adjacency list
n = 9
adj = [set() for _ in range(n)]
for u,v in edge_list:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
print("Degrees:", [len(adj[v]) for v in range(n)])

# Check independence number
max_ind_set = []
for r in range(1, n+1):
    for subset in itertools.combinations(range(n), r):
        # check if independent
        ok = True
        for i in range(len(subset)):
            for j in range(i+1, len(subset)):
                if subset[j] in adj[subset[i]]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            max_ind_set = subset
print("Max independent set size:", len(max_ind_set), "example:", max_ind_set)

# Check vertex connectivity using Menger's theorem / brute force
# Vertex connectivity is the minimum size of a vertex cut (excluding complete graph)
# Since n=9, we can brute force
from collections import deque

def is_connected(exclude):
    # BFS from first vertex not in exclude
    start = None
    for v in range(n):
        if v not in exclude:
            start = v
            break
    if start is None:
        return False
    visited = set([start])
    q = deque([start])
    while q:
        v = q.popleft()
        for u in adj[v]:
            if u not in exclude and u not in visited:
                visited.add(u)
                q.append(u)
    return len(visited) == n - len(exclude)

# Check if graph is complete (it's not, since degree 4 < 8)
# Find minimum vertex cut
min_cut = n
min_cut_sets = []
for k in range(1, n):
    found = False
    for cut in itertools.combinations(range(n), k):
        cut_set = set(cut)
        if not is_connected(cut_set):
            found = True
            break
    if found:
        min_cut = k
        break

print("Vertex connectivity:", min_cut)
